using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "DevourCustomBattleActionDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/Enemy/DevourCustomBattleActionDescription", order = 0)]
public class DevourCustomBattleActionDescription : CustomBattleActionDescription
{
	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		DevourAction devourAction = battleAction as DevourAction;
		return Smart.Format(devourAction.CorruptAction.GetActionDescription(GetFinalAmountWithoutEquation(amountModified))) + "\n" + Smart.Format(GetRawLocalizedDescription(battleAction), devourAction.DevourIncreaseAmount);
	}
}
